<?php
require_once __DIR__ . '/../includes/auth.php';
require_once __DIR__ . '/../includes/db.php';
requireRole(['administrator']);
$q = trim((string)($_GET['q'] ?? ''));
$conn = db();
$stmt = $conn->prepare("SELECT id, username, email, role, status FROM users WHERE username LIKE CONCAT('%', ?, '%') OR email LIKE CONCAT('%', ?, '%') ORDER BY username");
$stmt->bind_param('ss', $q, $q); $stmt->execute(); $users = $stmt->get_result()->fetch_all(MYSQLI_ASSOC); $stmt->close();
$hostels = $conn->query('SELECT id,name,location,capacity FROM hostel_profiles ORDER BY name')->fetch_all(MYSQLI_ASSOC);
$rooms = $conn->query('SELECT r.*,h.name hostel_name FROM rooms r JOIN hostel_profiles h ON h.id=r.hostel_id ORDER BY h.name,r.room_number')->fetch_all(MYSQLI_ASSOC);
$students = $conn->query("SELECT id,username FROM users WHERE role='student' AND status='active' ORDER BY username")->fetch_all(MYSQLI_ASSOC);
$wardens = $conn->query("SELECT id, username FROM users WHERE role='warden' AND status='active' ORDER BY username")->fetch_all(MYSQLI_ASSOC);
$wardenAssignments = $conn->query("SELECT wa.id, wa.warden_id, u.username AS warden_name, h.id AS hostel_id, h.name AS hostel_name
    FROM warden_assignments wa
    JOIN users u ON u.id = wa.warden_id
    JOIN hostel_profiles h ON h.id = wa.hostel_id
    WHERE wa.active = 1
    ORDER BY h.name, u.username")->fetch_all(MYSQLI_ASSOC);
?>
