<table class="dash-table"><tr><th>User</th><th>Role</th><th>Status</th><th>Actions</th></tr><?php foreach($users as $u): ?><tr><td><?= e($u['username']) ?><br><small><?= e($u['email']) ?></small></td><td><?= e(formatRole($u['role'])) ?></td><td><?= e($u['status']) ?></td><td><form method="post" action="actions.php"><?= csrfField() ?><input type="hidden" name="action" value="user_status"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><select name="status"><option <?= $u['status']==='active'?'selected':'' ?>>active</option><option <?= $u['status']==='inactive'?'selected':'' ?>>inactive</option><option <?= $u['status']==='suspended'?'selected':'' ?>>suspended</option></select><button class="btn btn-secondary btn-sm">Update</button></form><form method="post" action="actions.php"><?= csrfField() ?><input type="hidden" name="action" value="user_delete"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><button class="btn btn-secondary btn-sm">Delete</button></form></td></tr><?php endforeach; ?></table></section>
<section class="visual-card"><h2>Hostels and rooms</h2><form method="post" action="actions.php" class="admin-form"><?= csrfField() ?><input type="hidden" name="action" value="hostel_save"><input name="name" required placeholder="Hostel name"><input name="location" placeholder="Location"><input name="capacity" type="number" min="1" required placeholder="Capacity"><button class="btn btn-primary btn-sm">Add hostel</button></form>
<table class="dash-table"><tr><th>Hostel</th><th>Location</th><th>Capacity</th><th>Manage / add room</th></tr><?php foreach($hostels as $h): ?><tr><td colspan="3"><form method="post" action="actions.php"><?= csrfField() ?><input type="hidden" name="action" value="hostel_update"><input type="hidden" name="id" value="<?= (int)$h['id'] ?>"><input name="name" required value="<?= e($h['name']) ?>"><input name="location" value="<?= e($h['location']) ?>"><input name="capacity" type="number" min="1" value="<?= (int)$h['capacity'] ?>"><button class="btn btn-secondary btn-sm">Update</button></form></td><td><form method="post" action="actions.php"><?= csrfField() ?><input type="hidden" name="action" value="hostel_delete"><input type="hidden" name="id" value="<?= (int)$h['id'] ?>"><button class="btn btn-secondary btn-sm">Delete</button></form><form method="post" action="actions.php"><?= csrfField() ?><input type="hidden" name="action" value="room_save"><input type="hidden" name="hostel_id" value="<?= (int)$h['id'] ?>"><input name="room_number" required placeholder="Room"><input name="room_type" value="Standard"><input name="capacity" type="number" min="1" value="1"><button class="btn btn-secondary btn-sm">Add room</button></form></td></tr><?php endforeach; ?></table>
<table class="dash-table"><tr><th>Hostel</th><th>Room</th><th>Occupancy</th><th>Status / actions</th></tr><?php foreach($rooms as $r): ?><tr><td><?= e($r['hostel_name']) ?></td><td><form method="post" action="actions.php"><?= csrfField() ?><input type="hidden" name="action" value="room_update"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input name="room_number" value="<?= e($r['room_number']) ?>"><input name="room_type" value="<?= e($r['room_type']) ?>"><input name="capacity" type="number" min="1" value="<?= (int)$r['capacity'] ?>"></td><td><?= (int)$r['occupied'] ?>/<?= (int)$r['capacity'] ?></td><td><select name="status"><option <?= $r['status']==='available'?'selected':'' ?>>available</option><option <?= $r['status']==='occupied'?'selected':'' ?>>occupied</option><option <?= $r['status']==='maintenance'?'selected':'' ?>>maintenance</option></select><button class="btn btn-secondary btn-sm">Update</button></form><form method="post" action="actions.php"><?= csrfField() ?><input type="hidden" name="action" value="room_delete"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn btn-secondary btn-sm">Delete</button></form></td></tr><?php endforeach; ?></table></section>
<section class="visual-card"><h2>Warden hostel assignments</h2><form method="post" action="actions.php" class="admin-form"><?= csrfField() ?><input type="hidden" name="action" value="warden_assignment_save"><select name="warden_id" required><option value="">Select warden</option><?php foreach($wardens as $warden): ?><option value="<?= (int)$warden['id'] ?>"><?= e($warden['username']) ?></option><?php endforeach; ?></select><select name="hostel_id" required><option value="">Select hostel</option><?php foreach($hostels as $hostel): ?><option value="<?= (int)$hostel['id'] ?>"><?= e($hostel['name']) ?></option><?php endforeach; ?></select><button class="btn btn-primary btn-sm">Assign hostel</button></form>
<table class="dash-table"><tr><th>Warden</th><th>Hostel</th><th>Action</th></tr><?php foreach($wardenAssignments as $assignment): ?><tr><td><?= e($assignment['warden_name']) ?></td><td><?= e($assignment['hostel_name']) ?></td><td><form method="post" action="actions.php"><?= csrfField() ?><input type="hidden" name="action" value="warden_assignment_delete"><input type="hidden" name="id" value="<?= (int)$assignment['id'] ?>"><button class="btn btn-secondary btn-sm">Remove</button></form></td></tr><?php endforeach; ?><?php if (!$wardenAssignments): ?><tr><td colspan="3">No hostel assignments configured.</td></tr><?php endif; ?></table></section>
<section class="visual-card"><h2>Payment record entry</h2><form method="post" action="actions.php" class="admin-form"><?= csrfField() ?><input type="hidden" name="action" value="payment_save"><select name="user_id" required><option value="">Student</option><?php foreach($students as $s): ?><option value="<?= (int)$s['id'] ?>"><?= e($s['username']) ?></option><?php endforeach; ?></select><input name="reference_no" required maxlength="60" placeholder="Reference"><input name="amount" type="number" min="0" step=".01" required placeholder="Amount"><input name="balance" type="number" min="0" step=".01" required placeholder="Balance"><input name="payment_date" type="date" required value="<?= date('Y-m-d') ?>"><select name="status"><option>recorded</option><option>verified</option><option>pending_audit</option></select><button class="btn btn-primary btn-sm">Record payment</button></form></section>
